package com.odbscanner.spec

import org.json.JSONObject

/**
 * The shared diagnostic spec, generated by `tools/export_spec.py` from the
 * Python collector and bundled in assets as `spec.json`.
 *
 * This is the single source of truth for DID addresses, scale factors, the
 * read-only allow-list and the per-ECU transport quirks. The Android app must
 * never hard-code any of this: load it and follow it, so the two platforms
 * cannot drift.
 */

/** One decode recipe: either simple arithmetic or a named special decoder. */
sealed class Decode {
    /**
     * value = raw_integer[offset .. offset+length] * scale / divisor + addend
     * (big-endian, signedness as declared).
     */
    data class Scalar(
        val offset: Int,
        val length: Int,
        val signed: Boolean,
        val scale: Double,
        val divisor: Double,
        val addend: Double,
        val formula: String?,
    ) : Decode()

    /** A decoder that is not simple arithmetic; implement by name. */
    data class Special(val name: String, val formula: String?) : Decode()
}

data class EcuSpec(
    val key: String,
    val name: String,
    val tx: Int?,
    val rx: Int?,
    val tx29: Int?,
    val rx29: Int?,
    val addressing: String,        // "functional" | "11-bit" | "29-bit"
    val autoFormatting: Boolean,
    val flowControl: Boolean,
    val receiveFilter: Boolean,
)

data class MeasurementSpec(
    val key: String,
    val name: String,
    val unit: String,
    val ecuKey: String,
    val did: Int?,
    val slow: Boolean,
    val decode: Decode?,
)

data class CellVoltages(
    val ecuKey: String,
    val didBase: Int,
    val slots: Int,
    val unusedMarker: Int,
    val decode: Decode,
)

data class ReadOnlyGuard(
    val allowedServices: Map<Int, String>,
    val blockedServices: Map<Int, String>,
    val readSubfunctions: Map<Int, Set<Int>>,
    val minRequestBytes: Map<Int, Int>,
    val maxRequestBytes: Int,
    val nrcNames: Map<Int, String>,
)

data class ProfileSpec(
    val measurements: List<MeasurementSpec>,
    val cellVoltages: CellVoltages?,
)

data class Spec(
    val specVersion: String,
    val ecus: Map<String, EcuSpec>,
    val guard: ReadOnlyGuard,
    val profiles: Map<String, ProfileSpec>,
) {
    fun ecu(key: String): EcuSpec =
        ecus[key] ?: error("spec has no ECU '$key'")
}

/** Parse a "0x…" hex string into an Int, or null when absent/empty. */
private fun hex(value: Any?): Int? {
    if (value == null) return null
    val s = value.toString()
    if (s.isBlank() || s == "null" || s == "-") return null
    return s.removePrefix("0x").removePrefix("0X").toInt(16)
}

private fun parseDecode(obj: JSONObject?): Decode? {
    if (obj == null) return null
    return when (val kind = obj.optString("kind")) {
        "scalar" -> Decode.Scalar(
            offset = obj.getInt("offset"),
            length = obj.getInt("length"),
            signed = obj.getBoolean("signed"),
            scale = obj.getDouble("scale"),
            divisor = obj.getDouble("divisor"),
            addend = obj.getDouble("addend"),
            formula = obj.optString("formula").ifBlank { null },
        )
        "special" -> Decode.Special(
            name = obj.getString("name"),
            formula = obj.optString("formula").ifBlank { null },
        )
        else -> null
    }
}

object SpecLoader {
    fun load(json: String): Spec {
        val root = JSONObject(json)

        val guardJson = root.getJSONObject("read_only_guard")
        val guard = ReadOnlyGuard(
            allowedServices = mapFrom(guardJson.getJSONObject("allowed_services")),
            blockedServices = mapFrom(guardJson.getJSONObject("blocked_services")),
            readSubfunctions = guardJson.getJSONObject("read_subfunctions")
                .let { obj ->
                    obj.keys().asSequence().associate { k ->
                        hex(k)!! to obj.getJSONArray(k).let { arr ->
                            (0 until arr.length()).map { arr.getInt(it) }.toSet()
                        }
                    }
                },
            minRequestBytes = guardJson.getJSONObject("min_request_bytes")
                .let { obj ->
                    obj.keys().asSequence().associate { k ->
                        hex(k)!! to obj.getInt(k)
                    }
                },
            maxRequestBytes = guardJson.getInt("max_request_bytes"),
            nrcNames = mapFrom(guardJson.getJSONObject("nrc_names")),
        )

        val ecus = root.getJSONArray("ecus").let { arr ->
            (0 until arr.length()).map { i ->
                val e = arr.getJSONObject(i)
                val t = e.getJSONObject("transport")
                EcuSpec(
                    key = e.getString("key"),
                    name = e.getString("name"),
                    tx = hex(e.opt("tx")),
                    rx = hex(e.opt("rx")),
                    tx29 = hex(e.opt("tx29")),
                    rx29 = hex(e.opt("rx29")),
                    addressing = e.getString("addressing"),
                    autoFormatting = t.getBoolean("auto_formatting"),
                    flowControl = t.getBoolean("flow_control"),
                    receiveFilter = t.getBoolean("receive_filter"),
                )
            }.associateBy { it.key }
        }

        val profiles = root.getJSONObject("profiles").let { obj ->
            obj.keys().asSequence().associate { name ->
                name to parseProfile(obj.getJSONObject(name))
            }
        }

        return Spec(
            specVersion = root.getString("spec_version"),
            ecus = ecus,
            guard = guard,
            profiles = profiles,
        )
    }

    private fun mapFrom(obj: JSONObject): Map<Int, String> =
        obj.keys().asSequence().associate { k -> hex(k)!! to obj.getString(k) }

    private fun parseProfile(obj: JSONObject): ProfileSpec {
        val measurements = obj.getJSONArray("measurements").let { arr ->
            (0 until arr.length()).map { i ->
                val m = arr.getJSONObject(i)
                MeasurementSpec(
                    key = m.getString("key"),
                    name = m.getString("name"),
                    unit = m.getString("unit"),
                    ecuKey = m.getString("ecu_key"),
                    did = hex(m.opt("did")),
                    slow = m.optBoolean("slow", false),
                    decode = parseDecode(m.optJSONObject("decode")),
                )
            }
        }
        val cv = obj.optJSONObject("cell_voltages")
        val cellVoltages = cv?.let {
            val d = parseDecode(it.getJSONObject("decode"))
            if (d == null) {
                // A malformed cell_voltages entry must not crash the app; just
                // skip the per-cell sweep.
                null
            } else {
                CellVoltages(
                    ecuKey = it.getString("ecu_key"),
                    didBase = hex(it.getString("did_base"))!!,
                    slots = it.getInt("slots"),
                    unusedMarker = hex(it.getString("unused_marker"))!!,
                    decode = d,
                )
            }
        }
        return ProfileSpec(measurements, cellVoltages)
    }
}
